 package insurance

 import (
 	"encoding/json"
 	"fmt"
 	"net/http"
 	"time"
 )

+type Policy struct {
+	Number string `json:"number"`
+	Valid  bool   `json:"valid"`
+}
+
+func Check(number string) (Policy, error) {
+	client := &http.Client{Timeout: 5 * time.Second}
+
+	resp, err := client.Get(fmt.Sprintf("%s/policies/%s", baseURL, number))
+	if err != nil {
+		return Policy{}, err
+	}
+	defer resp.Body.Close()
+
+	var policy Policy
+	if err := json.NewDecoder(resp.Body).Decode(&policy); err != nil {
+		return Policy{}, err
+	}
+
+	return policy, nil
+}
